locked_choices as materialized(select c.* from lr_answer_choices c where c.question_id in(select id from locked_questions) for update),
locked_steps as materialized (select t.* from lr_explanation_steps t where t.explanation_id::text in (select eid from expected) for update),
locked_notes as materialized (select t.* from lr_explanation_choice_notes t where t.explanation_id::text in (select eid from expected) for update),
actual as (select 'step'::text kind,id::text rid,explanation_id::text eid,position::text slot,md5(body) body_md5,coalesce(label,'') label from locked_steps union all select 'note',id::text,explanation_id::text,letter::text,md5(body),null::text from locked_notes),
eligibility as materialized (select not exists(select 1 from choice_expected x where (select count(*) from locked_choices c join locked_questions q on q.id=c.question_id where q.qid=x.qid and c.letter::text=x.letter and md5(c.choice_text)=x.body_md5 and c.is_correct=x.is_correct)<>1) and not exists(select 1 from locked_choices c join locked_questions q on q.id=c.question_id where not exists(select 1 from choice_expected x where x.qid=q.qid and x.letter=c.letter::text)) and not exists(select 1 from question_expected x where (select count(*) from locked_explanations e join locked_questions q on q.id=e.question_id where e.id::text=x.eid and q.qid=x.qid and md5(q.stimulus)=x.stimulus_md5 and md5(q.prompt)=x.prompt_md5 and q.correct_choice::text=x.key)<>1) and not exists (
 select 1 from expected e where
 (e.rid is not null and (select count(*) from actual a where a.kind=e.kind and a.eid=e.eid and a.slot=e.slot)=1 and not exists(select 1 from actual a where a.kind=e.kind and a.eid=e.eid and a.slot=e.slot and a.rid=e.rid and a.body_md5=e.old_md5 and (e.kind='note' or a.label=e.old_label)))
 or (e.rid is not null and (select count(*) from actual a where a.kind=e.kind and a.eid=e.eid and a.slot=e.slot)<>1)
 or (e.rid is null and exists(select 1 from actual a where a.kind=e.kind and a.eid=e.eid and a.slot=e.slot))
 ) and not exists(select 1 from actual a where not exists(select 1 from expected e where a.kind=e.kind and a.eid=e.eid and a.slot=e.slot)) eligible),
us as (update lr_explanation_steps t set body=e.new_body,label=e.new_label from expected e,eligibility g where g.eligible and e.kind='step' and e.changed and e.rid is not null and t.id=e.rid::uuid and t.explanation_id=e.eid::uuid and t.position::text=e.slot and md5(t.body)=e.old_md5 and coalesce(t.label,'')=e.old_label returning t.id),
un as (update lr_explanation_choice_notes t set body=e.new_body from expected e,eligibility g where g.eligible and e.kind='note' and e.changed and e.rid is not null and t.id=e.rid::uuid and t.explanation_id=e.eid::uuid and t.letter::text=e.slot and md5(t.body)=e.old_md5 returning t.id),
is_ as (insert into lr_explanation_steps(explanation_id,position,label,body) select e.eid::uuid,e.slot::integer,e.new_label,e.new_body from expected e,eligibility g where g.eligible and e.kind='step' and e.rid is null and not exists(select 1 from lr_explanation_steps t where t.explanation_id=e.eid::uuid and t.position::text=e.slot) returning id),
in_ as (insert into lr_explanation_choice_notes(explanation_id,letter,body) select e.eid::uuid,e.slot,e.new_body from expected e,eligibility g where g.eligible and e.kind='note' and e.rid is null and not exists(select 1 from lr_explanation_choice_notes t where t.explanation_id=e.eid::uuid and t.letter::text=e.slot) returning id),
result as (select (select eligible from eligibility) eligible,(select count(*) from us) updated_steps,(select count(*) from un) updated_notes,(select count(*) from is_) inserted_steps,(select count(*) from in_) inserted_notes)
select *,1/(case when not eligible or (updated_steps=20 and updated_notes=40 and inserted_steps=0 and inserted_notes=0) then 1 else 0 end) atomic_assertion from result;
